// ─── File: SettlementReliabilityDemo.java ───
// Runnable demo: unreliable channel + retries + idempotency + reconciliation.

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class SettlementReliabilityDemo {

    private static final Logger log = Logger.getLogger("settlement");

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        UnreliableChannel channel = new UnreliableChannel(0.4, new Random(7)); // 40% loss, seeded
        PartnerBank partner = new PartnerBank();
        NationalBank national = new NationalBank(channel, partner, 5);

        // Settle Rajesh's payment despite a lossy network.
        national.settleWithRetry("PAY-123", new BigDecimal("50000"));

        // Reconcile the two ledgers at end of day — the safety net.
        new Reconciler().reconcile(national.ledger(), partner.ledger());
    }
}

// ─── model/SettlementRecord.java ───
class SettlementRecord {
    final String paymentRef; final BigDecimal amount; final String status;
    SettlementRecord(String ref, BigDecimal amount) { paymentRef = ref; this.amount = amount; status = "SETTLED"; }
}

// ─── channel/UnreliableChannel.java — drops messages randomly ───
class UnreliableChannel {
    private static final Logger log = Logger.getLogger("settlement");
    private final double dropProbability; private final Random rnd;
    UnreliableChannel(double dropProbability, Random rnd) { this.dropProbability = dropProbability; this.rnd = rnd; }
    // returns true if the message got through, false if lost in the valley
    boolean deliver(String what) {
        boolean lost = rnd.nextDouble() < dropProbability;
        if (lost) log.warning(() -> "[CHANNEL] message LOST: " + what);
        else log.fine(() -> "[CHANNEL] delivered: " + what);
        return !lost;
    }
}

// ─── bank/PartnerBank.java — idempotent settlement ───
class PartnerBank {
    private static final Logger log = Logger.getLogger("settlement");
    private final Map<String, SettlementRecord> settled = new LinkedHashMap<>();
    // Idempotent: settling the same ref twice has the effect of once.
    String settle(String ref, BigDecimal amount) {
        if (settled.containsKey(ref)) {
            log.info(() -> "[PARTNER] duplicate settle " + ref + " — already SETTLED (idempotent)");
            return "DONE";   // same result, no double credit
        }
        settled.put(ref, new SettlementRecord(ref, amount));
        log.info(() -> "[PARTNER] SETTLED " + ref + " Rs." + amount);
        return "DONE";
    }
    Map<String, SettlementRecord> ledger() { return settled; }
}

// ─── bank/NationalBank.java — ack + retry over unreliable channel ───
class NationalBank {
    private static final Logger log = Logger.getLogger("settlement");
    private final UnreliableChannel channel; private final PartnerBank partner; private final int maxAttempts;
    private final Map<String, SettlementRecord> ledger = new LinkedHashMap<>();
    NationalBank(UnreliableChannel channel, PartnerBank partner, int maxAttempts) {
        this.channel = channel; this.partner = partner; this.maxAttempts = maxAttempts;
    }
    void settleWithRetry(String ref, BigDecimal amount) {
        for (int attempt = 1; attempt <= maxAttempts; attempt++) {
            int a = attempt;
            log.info(() -> "[NATIONAL] attempt " + a + " send settle " + ref);
            boolean requestArrived = channel.deliver("settle " + ref);
            String ack = null;
            if (requestArrived) {
                String result = partner.settle(ref, amount);      // idempotent on partner side
                boolean ackArrived = channel.deliver("ack " + result);  // the ack can be LOST
                if (ackArrived) ack = result;
            }
            if ("DONE".equals(ack)) {
                ledger.put(ref, new SettlementRecord(ref, amount));
                log.info(() -> "[NATIONAL] ack received — recorded SETTLED " + ref);
                return;
            }
            log.warning(() -> "[NATIONAL] no ack (lost) — will retry " + ref);
        }
        // Could not confirm within retries → leave for reconciliation, do NOT assume failure.
        log.severe(() -> "[NATIONAL] gave up confirming " + ref + " — reconciliation will resolve it");
    }
    Map<String, SettlementRecord> ledger() { return ledger; }
}

// ─── recon/Reconciler.java — safety net ───
class Reconciler {
    private static final Logger log = Logger.getLogger("settlement");
    void reconcile(Map<String, SettlementRecord> nationalLedger, Map<String, SettlementRecord> partnerLedger) {
        Set<String> onlyPartner = new HashSet<>(partnerLedger.keySet());
        onlyPartner.removeAll(nationalLedger.keySet());
        if (onlyPartner.isEmpty()) {
            log.info("[RECON] ledgers agree — eventually consistent");
        } else {
            // Partner settled but our ack was lost → repair our ledger to converge.
            onlyPartner.forEach(ref -> {
                nationalLedger.put(ref, partnerLedger.get(ref));
                log.warning(() -> "[RECON] repaired: " + ref + " was SETTLED at partner but missing here — converged");
            });
        }
    }
}

// ─── BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tH:%1$tM:%1$tS %2$-7s %3$s%n",
                new Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
